import java.time.LocalDate;import java.time.temporal.ChronoUnit;
abstract class Assignment{String title;int maxMarks;LocalDate dueDate;Assignment(String t,int m,LocalDate d){title=t;maxMarks=m;dueDate=d;}public abstract double getPenaltyRate();}
class CodingAssignment extends Assignment{CodingAssignment(String t,int m,LocalDate d){super(t,m,d);}public double getPenaltyRate(){return .10;}}
class WrittenAssignment extends Assignment{WrittenAssignment(String t,int m,LocalDate d){super(t,m,d);}public double getPenaltyRate(){return .20;}}
class Submission{private String student;private Assignment assignment;private LocalDate submissionDate;private String status="Submitted";Submission(String s,Assignment a,LocalDate d){student=s;assignment=a;submissionDate=d;long late=Math.max(0,ChronoUnit.DAYS.between(a.dueDate,d));System.out.println(s+"'s submission for '"+a.title+"' received ("+(late==0?"on time":late+" days late")+"). Status: "+status+".");}public String getStatus(){return status;}public void grade(int marks){if(!status.equals("Submitted")){System.out.println("Cannot grade: submission is already graded.");return;}if(marks<0||marks>assignment.maxMarks){System.out.println("Invalid marks.");return;}long late=Math.max(0,ChronoUnit.DAYS.between(assignment.dueDate,submissionDate));double penalty=Math.min(1.0,late*assignment.getPenaltyRate());int finalMarks=(int)Math.round(marks*(1-penalty));if(late==0)System.out.println(student+" graded: "+finalMarks+"/"+assignment.maxMarks+".");else System.out.println(student+" graded: "+finalMarks+"/"+assignment.maxMarks+" after "+(int)Math.round(penalty*100)+"% late penalty.");status="Graded";System.out.println("Status: "+status+".");}public boolean resubmit(LocalDate d){if(status.equals("Graded")){System.out.println("Cannot resubmit: '"+assignment.title+"' has already been graded.");return false;}submissionDate=d;System.out.println("Resubmission received.");return true;}}
public class AssignmentSubmissionPortal{public static void main(String[] args){Assignment c=new CodingAssignment("Linked List Lab",50,LocalDate.of(2026,3,10));Assignment w=new WrittenAssignment("Design Essay",50,LocalDate.of(2026,3,12));Submission a=new Submission("Asha",c,LocalDate.of(2026,3,10));Submission r=new Submission("Ravi",w,LocalDate.of(2026,3,14));a.grade(45);r.grade(40);a.resubmit(LocalDate.of(2026,3,15));}}